160	// restoreVersions 恢复并校验版本登记。
161	func (s *Store) restoreVersions(disk map[string]diskVersion) error {
162		out := make(map[string]*versionState, len(disk))
163		for k, dv := range disk {
164			if k == "" || dv.Target == "" || k != dv.Target {
165				return fmt.Errorf("%w: invalid upgrade version entry", ErrCorruptStorage)
166			}
167			if err := validateAllowedFrom(dv.Target, dv.AllowedFrom); err != nil {
168				return fmt.Errorf("%w: version %s: %v", ErrCorruptStorage, dv.Target, err)
169			}
170			out[k] = &versionState{Target: dv.Target, AllowedFrom: append([]string(nil), dv.AllowedFrom...)}
171		}
172		s.versions = out
173		return nil
174	}
175	
176	// expectedHist 是从已保存操作结果推导出的应有历史条目。
177	type expectedHist struct {
178		deviceID string
179		stage    string
180		op       diskOp
181	}
182	
183	// restoreCampaigns 恢复活动并做一致性校验。版本、设备引用、操作标识、
184	// 结果历史都必须自洽，否则整个存储拒绝打开。
185	func (s *Store) restoreCampaigns(disk map[string]diskCampaign) error {
186		out := make(map[string]*campaignState, len(disk))
187		for id, dc := range disk {
188			if id == "" || dc.ID != id {
189				return fmt.Errorf("%w: campaign id mismatch", ErrCorruptStorage)
190			}
191			if dc.Operator == "" || dc.Target == "" || dc.BatchSize <= 0 {
192				return fmt.Errorf("%w: campaign %s invalid", ErrCorruptStorage, id)
193			}
194			if dc.CreatedAt.IsZero() || dc.WindowStart.IsZero() || dc.WindowEnd.IsZero() || dc.Deadline.IsZero() {
195				return fmt.Errorf("%w: campaign %s missing time", ErrCorruptStorage, id)
196			}
197			if !dc.WindowStart.Before(dc.WindowEnd) || !dc.Deadline.After(dc.CreatedAt) {
198				return fmt.Errorf("%w: campaign %s invalid time range", ErrCorruptStorage, id)
199			}
200			if _, ok := s.versions[dc.Target]; !ok {
201				return fmt.Errorf("%w: campaign %s target %s missing", ErrCorruptStorage, id, dc.Target)
202			}
203			if dc.Status != CampaignRunning && dc.Status != CampaignSucceeded && dc.Status != CampaignFailed {
204				return fmt.Errorf("%w: campaign %s bad status", ErrCorruptStorage, id)
205			}
206			if dc.IDScheme != opIDSchemeLegacy && dc.IDScheme != opIDSchemeV2 {
207				return fmt.Errorf("%w: campaign %s unknown operation id scheme", ErrCorruptStorage, id)
208			}
209			if dc.Ended == (dc.Status == CampaignRunning) {
210				return fmt.Errorf("%w: campaign %s ended/status mismatch", ErrCorruptStorage, id)
211			}
212			if len(dc.Devices) == 0 {
213				return fmt.Errorf("%w: campaign %s has no devices", ErrCorruptStorage, id)
214			}
215			c := &campaignState{
216				ID:                dc.ID,
217				Operator:          dc.Operator,
218				Target:            dc.Target,
219				CreatedAt:         dc.CreatedAt,
220				BatchSize:         dc.BatchSize,
221				WindowStart:       dc.WindowStart,
222				WindowEnd:         dc.WindowEnd,
223				Deadline:          dc.Deadline,
224				RollbackOnFailure: dc.RollbackOnFailure,
225				idScheme:          dc.IDScheme,
226				LastTime:          dc.LastTime,
227				Status:            dc.Status,
228				Ended:             dc.Ended,
229				EndedAt:           dc.EndedAt,
230				index:             map[string]int{},
231			}
232			// 旧记录可能没有时间基线：缺省（零值）时仍以创建时间作为基线。
233			// 基线与各业务记录时间是否自洽在设备与历史全部恢复后统一检查。
234			if c.LastTime.IsZero() {
235				c.LastTime = c.CreatedAt
236			}
237			seen := map[string]bool{}
238			// expected 按操作标识收集每个已有结果（HasResult）的下载/安装/回滚
239			// 操作所对应的唯一应有历史条目，随后与保存的结果历史逐条对账。
240			expected := map[string]expectedHist{}
241			for i, dd := range dc.Devices {
242				if dd.DeviceID == "" || seen[dd.DeviceID] {
243					return fmt.Errorf("%w: campaign %s device list invalid", ErrCorruptStorage, id)
244				}
245				seen[dd.DeviceID] = true
246				if _, ok := s.devices[dd.DeviceID]; !ok {
247					return fmt.Errorf("%w: campaign %s device %s missing", ErrCorruptStorage, id, dd.DeviceID)
248				}
249				if dd.Batch != i/dc.BatchSize {
250					return fmt.Errorf("%w: campaign %s batch mismatch", ErrCorruptStorage, id)
251				}
252				if !validDeviceStatus(dd.Status) {
253					return fmt.Errorf("%w: campaign %s bad device status", ErrCorruptStorage, id)
254				}
255				if dd.Phase != StageDownload && dd.Phase != StageInstall && dd.Phase != StageRollback {
256					return fmt.Errorf("%w: campaign %s bad phase", ErrCorruptStorage, id)
257				}
258				if dc.IDScheme == opIDSchemeV2 {
259					// 新方案：标识必须是无歧义编码且恰好归属本活动、本设备、本阶段。
260					if !validV2OpID(dd.Download.ID, id, dd.DeviceID, StageDownload) ||
261						!validV2OpID(dd.Install.ID, id, dd.DeviceID, StageInstall) ||
262						!validV2OpID(dd.Rollback.ID, id, dd.DeviceID, StageRollback) {
263						return fmt.Errorf("%w: campaign %s operation id mismatch", ErrCorruptStorage, id)
264					}
265				} else {
266					wantDL := operationID(id, dd.DeviceID, StageDownload)
267					wantIN := operationID(id, dd.DeviceID, StageInstall)
268					wantRB := operationID(id, dd.DeviceID, StageRollback)
269					if dd.Download.ID != wantDL || dd.Install.ID != wantIN {
270						return fmt.Errorf("%w: campaign %s operation id mismatch", ErrCorruptStorage, id)
271					}
272					if dc.RollbackOnFailure {
273						if dd.Rollback.ID != wantRB {
274							return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
275						}
276					} else if dd.Rollback.ID != "" && dd.Rollback.ID != wantRB {
277						// 未开启回滚的旧活动：回滚标识允许缺省或等于旧稳定标识。
278						return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
279					}
280				}
281				if !dc.RollbackOnFailure {
282					// 未开启回滚的活动（含旧存储）不得残留任何回滚进展。
283					if dd.RollbackTarget != "" ||
284						dd.Rollback.Claimed || dd.Rollback.HasResult ||
285						dd.Status == DeviceAwaitingRollback || dd.Status == DeviceRollingBack ||
286						dd.Phase == StageRollback || isRollbackTerminal(dd.Status) {
287						return fmt.Errorf("%w: campaign %s rollback state in non-rollback campaign", ErrCorruptStorage, id)
288					}
289				}
290				// 终态设备必须带时间；失败还须带阶段与原因。
291				if isTerminal(dd.Status) && dd.At.IsZero() {
292					return fmt.Errorf("%w: campaign %s terminal without time", ErrCorruptStorage, id)
293				}
294				if dd.Status == DeviceFailed && dd.Reason == "" {
295					return fmt.Errorf("%w: campaign %s failure without reason", ErrCorruptStorage, id)
296				}
297				if (dd.Status == DeviceRollbackFailed || dd.Status == DeviceRollbackTimeout ||
298					dd.Status == DeviceAwaitingRollback) && dd.Reason == "" {
299					return fmt.Errorf("%w: campaign %s rollback without reason", ErrCorruptStorage, id)
300				}
301				if dd.Status == DeviceSucceeded &&
302					!(dd.Download.HasResult && dd.Download.Success && dd.Install.HasResult && dd.Install.Success) {
303					return fmt.Errorf("%w: campaign %s succeeded device without results", ErrCorruptStorage, id)
304				}
305				if dd.Status == DeviceFailed {
306					failedOp := dd.Download
307					if dd.Phase == StageInstall {
308						failedOp = dd.Install
309					}
310					if !failedOp.HasResult || failedOp.Success {
311						return fmt.Errorf("%w: campaign %s failed device without failed result", ErrCorruptStorage, id)
312					}
313				}
314				if dd.Status == DeviceReady && !(dd.Download.HasResult && dd.Download.Success) {
315					return fmt.Errorf("%w: campaign %s ready device without download", ErrCorruptStorage, id)
316				}
317				ops := []diskOp{dd.Download, dd.Install}
318				if dc.RollbackOnFailure {
319					ops = append(ops, dd.Rollback)
320				}
321				for _, o := range ops {
322					if o.HasResult {
323						if !o.Claimed {
324							return fmt.Errorf("%w: campaign %s unclaimed result", ErrCorruptStorage, id)
325						}
326						if o.At.IsZero() {
327							return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
328						}
329						if !o.Success && o.Reason == "" {
330							return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
331						}
332					}
333					if o.Claimed && o.ClaimedAt.IsZero() {
334						return fmt.Errorf("%w: campaign %s claim without time", ErrCorruptStorage, id)
335					}
336				}
337				if dd.Install.HasResult && !(dd.Download.HasResult && dd.Download.Success) {
338					return fmt.Errorf("%w: campaign %s install before download", ErrCorruptStorage, id)
339				}
340				if dd.Install.Claimed && !(dd.Download.HasResult && dd.Download.Success) {
341					return fmt.Errorf("%w: campaign %s install claimed before download", ErrCorruptStorage, id)
342				}
343				if dd.Install.HasResult && dd.Install.Success {
344					if dd.Install.ResultVersion != dc.Target {
345						return fmt.Errorf("%w: campaign %s install version mismatch", ErrCorruptStorage, id)
346					}
347					if _, ok := decodeObject(dd.Install.ResultConfig); !ok {
348						return fmt.Errorf("%w: campaign %s install config invalid", ErrCorruptStorage, id)
349					}
350				}
351				if dc.RollbackOnFailure {
352					if err := validateRollbackDisk(id, dd); err != nil {
353						return err
354					}
355				}
356				rbOp := decodeOp(dd.Rollback)
357				if !dc.RollbackOnFailure {
358					// 与创建路径一致：内存中始终持有本方案稳定的回滚操作标识。
359					if dc.IDScheme == opIDSchemeV2 {
360						rbOp = opState{ID: dd.Rollback.ID}
361					} else {
362						rbOp = opState{ID: operationID(id, dd.DeviceID, StageRollback)}
363					}
364				}
365				cd := &campaignDevice{
366					DeviceID:       dd.DeviceID,
367					Batch:          dd.Batch,
368					Status:         dd.Status,
369					Phase:          dd.Phase,
370					Reason:         dd.Reason,
371					At:             dd.At,
372					Download:       decodeOp(dd.Download),
373					Install:        decodeOp(dd.Install),
374					Rollback:       rbOp,
375					RollbackTarget: dd.RollbackTarget,
376				}
377				c.index[cd.DeviceID] = len(c.Devices)
378				c.Devices = append(c.Devices, cd)
379				// 每个已有结果的操作都应当恰好对应一条结果历史；
380				// 已领取未完成、超时或因前批失败而未执行的阶段没有结果，不入账。
381				addExpected := func(o diskOp, stage string) {
382					if !o.HasResult {
383						return
384					}
385					expected[o.ID] = expectedHist{deviceID: dd.DeviceID, stage: stage, op: o}
386				}
387				addExpected(dd.Download, StageDownload)
388				addExpected(dd.Install, StageInstall)
389				if dc.RollbackOnFailure {
390					addExpected(dd.Rollback, StageRollback)
391				}
392			}
393			// seenHistory 记录已经与保存历史对过账的操作标识。
394			seenHistory := map[string]bool{}
395			var prevAt time.Time
396			for i, dr := range dc.Results {
397				if dr.At.IsZero() {
398					return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
399				}
400				// 历史按接受顺序保存：时间不得倒退；同一时刻按保存次序排列。
401				if i > 0 && dr.At.Before(prevAt) {
402					return fmt.Errorf("%w: campaign %s result history out of order", ErrCorruptStorage, id)
403				}
404				prevAt = dr.At
405				if _, ok := c.index[dr.DeviceID]; !ok {
406					return fmt.Errorf("%w: campaign %s result device mismatch", ErrCorruptStorage, id)
407				}
408				if dr.Stage != StageDownload && dr.Stage != StageInstall && dr.Stage != StageRollback {
409					return fmt.Errorf("%w: campaign %s result stage invalid", ErrCorruptStorage, id)
410				}
411				if dr.Stage == StageRollback && !dc.RollbackOnFailure {
412					return fmt.Errorf("%w: campaign %s rollback result in non-rollback campaign", ErrCorruptStorage, id)
413				}
414				if dc.IDScheme == opIDSchemeLegacy {
415					// 旧方案标识可按（活动, 设备, 阶段）直接重算；新方案标识的
416					// 归属已在设备操作校验中确认，这里靠下方的历史对账锚定。
417					if wantOp := operationID(id, dr.DeviceID, dr.Stage); dr.OperationID != wantOp {
418						return fmt.Errorf("%w: campaign %s result op id mismatch", ErrCorruptStorage, id)
419					}
420				}
421				if seenHistory[dr.OperationID] {
422					return fmt.Errorf("%w: campaign %s duplicated result history", ErrCorruptStorage, id)
423				}
424				seenHistory[dr.OperationID] = true
425				// 历史必须对应该设备该阶段实际已有的结果：多出记录、设备或阶段不符
426				// 都按损坏处理，不能通过删历史或补结果把矛盾隐藏起来。
427				want, ok := expected[dr.OperationID]
428				if !ok {
429					return fmt.Errorf("%w: campaign %s result history without operation result", ErrCorruptStorage, id)
430				}
431				if want.deviceID != dr.DeviceID || want.stage != dr.Stage {
432					return fmt.Errorf("%w: campaign %s result history stage mismatch", ErrCorruptStorage, id)
433				}
434				if !dr.Success && dr.Reason == "" {
435					return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
436				}
437				o := want.op
438				if o.Success != dr.Success {
439					return fmt.Errorf("%w: campaign %s result history success mismatch", ErrCorruptStorage, id)
440				}
441				// 失败原因必须一致。成功结果的原因不进入历史（提交路径亦不拒绝
442				// 成功结果附带原因），故只对失败结果比对原因。
443				if !o.Success && o.Reason != dr.Reason {
444					return fmt.Errorf("%w: campaign %s result history reason mismatch", ErrCorruptStorage, id)
445				}
446				// 时间按同一时刻判断，不因时区表示不同而冲突。
447				if !o.At.Equal(dr.At) {
448					return fmt.Errorf("%w: campaign %s result history time mismatch", ErrCorruptStorage, id)
449				}
450				// 安装或回滚成功时记录的版本必须与当次操作接受的版本一致。
451				if dr.Success && (dr.Stage == StageInstall || dr.Stage == StageRollback) {
452					if dr.Version != o.ResultVersion || dr.Version == "" {
453						return fmt.Errorf("%w: campaign %s result history version mismatch", ErrCorruptStorage, id)
454					}
455				} else if dr.Version != "" {
456					// 下载成功及任何失败结果都不携带版本。
457					return fmt.Errorf("%w: campaign %s result history with unexpected version", ErrCorruptStorage, id)
458				}
459				c.Results = append(c.Results, ResultRecord{
460					DeviceID:    dr.DeviceID,
461					OperationID: dr.OperationID,
462					Stage:       dr.Stage,
463					Success:     dr.Success,
464					Reason:      dr.Reason,
465					Version:     dr.Version,
466					At:          dr.At,
467				})
468			}
469			// 反向对账：每个已有结果的操作都必须恰好有一条历史；缺少记录即损坏。
470			for opID, want := range expected {
471				if !seenHistory[opID] {
472					return fmt.Errorf("%w: campaign %s device %s %s result missing history",
473						ErrCorruptStorage, id, want.deviceID, want.stage)
474				}
475			}
476			// 活动整体结论必须与设备进度一致：任一设备仍处于非终态（等待下载、
477			// 下载中、等待安装、安装中、等待回滚、回滚中），活动必须 running 且
478			// Ended 为 false；全部设备终态时活动必须已结束，且只有每台设备都
479			// succeeded 才能 succeeded，其余组合（失败、超时、未执行，以及回滚
480			// 成功/失败/超时——回滚成功只是恢复原版本，不算本次升级成功）只能
481			// failed。设备离线或维护窗口结束不改变这一判断。
482			allTerminal := true
483			allSucceeded := true
484			for _, cd := range c.Devices {
485				if !isTerminal(cd.Status) {
486					allTerminal = false
487				}
488				if cd.Status != DeviceSucceeded {
489					allSucceeded = false
490				}
491			}
492			if !allTerminal {
493				if c.Ended || c.Status != CampaignRunning {
494					return fmt.Errorf("%w: campaign %s ended while devices unfinished", ErrCorruptStorage, id)
495				}
496			} else {
497				wantStatus := CampaignFailed
498				if allSucceeded {
499					wantStatus = CampaignSucceeded
500				}
501				if !c.Ended || c.Status != wantStatus {
502					return fmt.Errorf("%w: campaign %s status %s does not match device results",
503						ErrCorruptStorage, id, c.Status)
504				}
505			}
506			// 时间基线必须能解释全部已存在的业务记录，否则重开后本应被拒绝的
507			// 旧时间请求又能推进活动。不能抬高基线或改写任何记录来掩盖矛盾。
508			if err := checkCampaignTimeBaseline(id, c); err != nil {
509				return err
510			}
511			out[id] = c
512		}
513		// 设备不能同时参加多个未结束活动。
514		busy := map[string]string{}
515		for id, c := range out {
516			if c.Ended {
517				continue
518			}
519			for _, cd := range c.Devices {
520				if other, ok := busy[cd.DeviceID]; ok {
521					return fmt.Errorf("%w: device %s in active campaigns %s and %s",
522						ErrCorruptStorage, cd.DeviceID, other, id)
523				}
524				busy[cd.DeviceID] = id
525			}
526		}
527		s.campaigns = out
528		return nil
529	}
530	
531	// checkCampaignTimeBaseline 校验活动时间基线（已接受的最新时间）与保存的
532	// 业务记录自洽：基线必须不早于创建时间、任一设备已经领取下载/安装/回滚的
533	// 时间、任一操作首次接受结果的时间、设备当前状态中已记录的时间；活动已结束
534	// 时还必须不早于保存的结束时间。只比较确实存在的记录：尚未领取的操作没有
535	// 领取时间、尚未接受结果的操作没有结果时间、新建且尚未推进的设备允许没有
536	// 状态时间，这些正常缺省值不导致打开失败。比较按绝对时刻进行，相等合法。
537	func checkCampaignTimeBaseline(campaignID string, c *campaignState) error {
538		baseline := c.LastTime
539		bad := func(format string, args ...any) error {
540			msg := fmt.Sprintf(format, args...)
541			return fmt.Errorf("%w: campaign %s time baseline %s %s",
542				ErrCorruptStorage, campaignID, baseline.Format(time.RFC3339Nano), msg)
543		}
544		if baseline.Before(c.CreatedAt) {
545			return bad("before creation time %s", c.CreatedAt.Format(time.RFC3339Nano))
546		}
547		if c.Ended && !c.EndedAt.IsZero() && baseline.Before(c.EndedAt) {
548			return bad("before end time %s", c.EndedAt.Format(time.RFC3339Nano))
549		}
550		for _, cd := range c.Devices {
551			if !cd.At.IsZero() && baseline.Before(cd.At) {
552				return bad("before device %s state time %s",
553					cd.DeviceID, cd.At.Format(time.RFC3339Nano))
554			}
555			// 已领取（含尚未完成）的操作一定接受过携带领取时刻的请求；
556			// 已接受结果的操作还必须比较首次接受结果的时间。未领取/未接受
557			// 的操作对应时间为零值，属正常缺省，跳过比较。
558			ops := []struct {
559				stage string
560				op    *opState
561			}{
562				{StageDownload, &cd.Download},
563				{StageInstall, &cd.Install},
564				{StageRollback, &cd.Rollback},
565			}
566			for _, item := range ops {
567				if !item.op.ClaimedAt.IsZero() && baseline.Before(item.op.ClaimedAt) {
568					return bad("before device %s %s claim time %s",
569						cd.DeviceID, item.stage, item.op.ClaimedAt.Format(time.RFC3339Nano))
570				}
571				if item.op.HasResult && !item.op.At.IsZero() && baseline.Before(item.op.At) {
572					return bad("before device %s %s result time %s",
573						cd.DeviceID, item.stage, item.op.At.Format(time.RFC3339Nano))
574				}
575			}
576		}
577		return nil
578	}
579	
580	func validDeviceStatus(status string) bool {
581		switch status {
582		case DevicePending, DeviceDownloading, DeviceReady, DeviceInstalling,
583			DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
584			DeviceAwaitingRollback, DeviceRollingBack,
585			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
586			return true
587		default:
588			return false
589		}
590	}
591	
592	// isRollbackTerminal 判断状态是否属于回滚相关终态。
593	func isRollbackTerminal(status string) bool {
594		switch status {
595		case DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
596			return true
597		default:
598			return false
599		}
600	}
601	
602	// isRollbackFlowStatus 判断状态是否处于回滚流程（等待/进行中/任一回滚终态）。
603	func isRollbackFlowStatus(status string) bool {
604		switch status {
605		case DeviceAwaitingRollback, DeviceRollingBack,
606			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
607			return true
608		default:
609			return false
610		}
611	}
612	
613	// validateRollbackDisk 校验开启回滚的活动中单台设备的回滚状态自洽。
614	func validateRollbackDisk(campaignID string, dd diskDev) error {
615		bad := func(msg string) error {
616			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
617		}
618		rb := dd.Rollback
619		// 回滚目标只能在首次领取下载时或之后锁定：有目标就必已领取下载。
620		// 反向不成立——领取下载时复查版本不兼容会直接失败，不锁定目标、也不回滚。
621		if dd.RollbackTarget != "" && !dd.Download.Claimed {
622			return bad("rollback target locked before download claim")
623		}
624		// 已领取下载且尚无下载结果，或已有成功下载结果：回滚目标必须已锁定，
625		// 字段缺失与空串按同一种损坏处理。这项要求不因设备进入安装阶段或
626		// 活动已结束而取消——否则安装失败后会留下没有明确恢复版本的回滚待办。
627		// 不能用当前影子版本、活动目标版本或允许升级列表替代丢失的目标。
628		// 首次领取前复查版本不兼容、直接在下载阶段失败的设备（下载已有失败
629		// 结果）允许没有目标：这种失败不进入安装或回滚。
630		if dd.RollbackTarget == "" && dd.Download.Claimed &&
631			(!dd.Download.HasResult || dd.Download.Success) {
632			return bad("missing locked rollback target")
633		}
634		// 进入回滚流程的设备必然经过成功下载，目标一定已锁定。
635		if isRollbackFlowStatus(dd.Status) && dd.RollbackTarget == "" {
636			return bad("rollback status without locked target")
637		}
638		switch dd.Status {
639		case DeviceAwaitingRollback:
640			// 已接受安装失败、回滚尚未领取：回滚无结果。
641			if dd.Phase != StageRollback || rb.Claimed || rb.HasResult {
642				return bad("awaiting rollback state mismatch")
643			}
644			if !(dd.Install.HasResult && !dd.Install.Success) {
645				return bad("awaiting rollback without install failure")
646			}
647		case DeviceRollingBack:
648			if dd.Phase != StageRollback || !rb.Claimed || rb.HasResult {
649				return bad("rolling back state mismatch")
650			}
651		case DeviceRollbackSucceeded:
652			if dd.Phase != StageRollback || !rb.HasResult || !rb.Success {
653				return bad("rollback succeeded without success result")
654			}
655			if rb.ResultVersion != dd.RollbackTarget {
656				return bad("rollback version mismatch")
657			}
658			if _, ok := decodeObject(rb.ResultConfig); !ok {
659				return bad("rollback config invalid")
660			}
661		case DeviceRollbackFailed:
662			if dd.Phase != StageRollback || !rb.HasResult || rb.Success || rb.Reason == "" {
663				return bad("rollback failed without failure result")
664			}
665		case DeviceRollbackTimeout:
666			if dd.Phase != StageRollback {
667				return bad("rollback timeout phase mismatch")
668			}
669			// 等待回滚超时（未领取）或正在回滚超时（已领取未完成）都可能。
670			if rb.HasResult {
671				return bad("rollback timeout with result")
672			}
673		default:
674			// 其余状态：开启回滚后安装一旦失败必然进入回滚流程，
675			// 因此这里不能有安装失败，回滚操作也必须从未被领取或提交；
676			// 但回滚目标可能因已领取下载而存在（下载失败/超时/成功等）。
677			if dd.Install.HasResult && !dd.Install.Success {
678				return bad("install failure without rollback state")
679			}
680			if rb.Claimed || rb.HasResult {
681				return bad("rollback progressed without install failure")
682			}
683		}
684		return nil
685	}
686

